mkdir -p /work/avra/packages/std-avrac/src/features/enums/tests/payload_proven && cd $_ && cat > payload_proven.av <<'EOF'
// proves: a payload read with no bounds test only where a test of its enum's tag that chose its
// variant stands before it, and every other way to a payload still answers rightly — a switch's
// case and its arm for the rest, a chain's tested arms and its untested last, nested variants, an
// or-pattern, a guard, a catch naming some or all of an error's variants, `?`, `is`, a task's cell
// and a fn box's code, each over variants of different widths in one enum.
enum Shape {
    Dot
    Line(len: int)
    Rect(w: int, h: int)
    Named(label: string, inner: Shape)
}

enum Fault {
    Short(n: int)
    Long(text: string)
}

fn area(s: Shape) -> int {
    match s {
        .Dot -> 0
        .Line(len) -> len
        .Rect(w, h) -> w * h
        .Named(_, inner) -> area(inner)
    }
}

fn nested(s: Shape) -> string {
    match s {
        .Named(label, .Rect(w, _)) -> "${label}:${w}"
        .Named(label, .Line(len)) -> "${label}-${len}"
        .Line(n) or .Rect(n, _) -> "n${n}"
        _ -> "?"
    }
}

fn guarded(s: Shape) -> int {
    match s {
        .Rect(w, h) if w > h -> w
        .Rect(_, h) -> h
        .Line(len) if len > 2 -> len * 10
        _ -> 1
    }
}

fn faulty(k: int) -> Result<int, Fault> {
    if k == 0 { return .Ok(7) }
    if k == 1 { return .Err(Fault.Short(k)) }
    .Err(Fault.Long("long${k}"))
}

fn caught_all(k: int) -> string {
    let r = faulty(k) catch {
        .Short(n) -> n * 100
        .Long(text) -> text.length
    }
    "${r}"
}

fn caught_some(k: int) -> Result<int, Fault> {
    let r = faulty(k) catch { .Short(n) -> n + 40 }
    .Ok(r + 1)
}

fn asked(k: int) -> Result<int, Fault> {
    let v = faulty(k)?
    .Ok(v * 2)
}

fn shown(r: Result<int, Fault>) -> string {
    match r {
        .Ok(v) -> "ok${v}"
        .Err(.Short(n)) -> "short${n}"
        .Err(.Long(t)) -> "long:${t}"
    }
}

fn is_rect(s: Shape) -> int { if s is .Rect(w, h) { w + h } else { 0 - 1 } }

let shapes = [Shape.Dot, Shape.Line(3), Shape.Rect(4, 2), Shape.Named("n", Shape.Rect(5, 6)), Shape.Named("m", Shape.Line(9)), Shape.Rect(1, 8)]
let areas = [area(s) for s in shapes]
let nests = [nested(s) for s in shapes]
let guards = [guarded(s) for s in shapes]
let doubled = (x: int) -> x * 2
let t = spawn { area(Shape.Rect(3, 3)) }
let waited = t.await
"${areas} ${nests} ${guards} ${caught_all(1)} ${caught_all(5)} ${shown(caught_some(1))} ${shown(caught_some(3))} ${shown(asked(0))} ${shown(asked(1))} ${shown(asked(4))} ${is_rect(shapes[2])} ${is_rect(shapes[1])} ${doubled(waited)}"
EOF
