rows=[l.split() for l in open('/work/lane/gp/sites.txt')]
def dem(s):
    s=re.sub(r'^av_','',s)
    return re.sub(r'\$([0-9A-F]{2})',lambda m:chr(int(m.group(1),16)),s)
for c,a,f in rows:
    tot[dem(f)]+=int(c); n[dem(f)]+=1
print("sum of the top 60 sites:", sum(int(r[0]) for r in rows))
for f,c in tot.most_common(25): print(f"{c:>11}  {n[f]:>2} site(s)  {f}")
EOF

