type Bag = { items: List<string> }

fn popped() -> string {
    mut xs = ["a", "b", "c", "d"]
    mut out = ""
    for x in xs {
        let _ = xs.pop()
        out = out + x
    }
    "${out}/${xs.length}"
}

fn rebound() -> string {
    mut xs = ["p", "q", "r"]
    mut out = ""
    for x in xs {
        xs = []
        out = out + x
    }
    "${out}/${xs.length}"
