// AN `if` WHOSE SEAT LIFTS ITS VALUE lifts it once, past the merge: each branch joins as the `if`'s
// own type, so branches seated as a nullable or a `Result` still meet at one phi of one layout.
fn tail(neg: bool, n: int) -> int? { if neg { n } else { 0 - n } }

fn held(neg: bool, n: int) -> int? {
    let r: int? = if neg { n } else { 0 - n }
    r
}

fn chained(k: int, n: int) -> int? { if k == 0 { n } else if k == 1 { 0 - n } else { 7 } }

fn mixed(k: int) -> int? { if k == 0 { null } else if k == 1 { 5 } else { return 8 } }

fn okayed(c: bool) -> Result<int, string> { if c { 4 } else { 6 } }

fn ok_or_zero(r: Result<int, string>) -> int { match r { .Ok(v) -> v, .Err(_) -> 0 } }

