/// A branch's value as the region of the `if`'s type `ty` joins it: born as its own type and lifted
/// into `ty`, never into the branch's own seat, which is the `if`'s and lifts the joined value once;
/// or where it leaves, nothing of `ty`.
fn branch(mut cx: Lowering, x: ExprId, ty: SignedType) -> Reg {
    let made = cx.born(x)
    if cx.store.leaves(x) { return cx.hollow_of(ty) }
    let own? = cx.worn_as(made) ?? cx.type_at(cx.meaning_of(x)) else { return made }
    cx.lifted(made, own, ty)
}

