//! A VALUE LIFTED INTO ITS SEAT: what `SignedType.reaches` judges, made. A seat that takes a value
//! as more than it is (a nullable of it, a union it's a member of, a `Result` it's the `Ok` of) is
//! where that value takes its wider layout, at the one edge every node passes through. A fn seat that
//! hands a place where the fn takes a value is where the fn is boxed behind the code that reads the place.

impl Lowering {
    /// `r`, a value of `from`, as a seat of `into` holds it: itself where the seat takes it as it is
    /// or doesn't take it at all.
    mut fn lifted(r: Reg, from: SignedType, into: SignedType) -> Reg {
        if self.program.checked.rewrites(from, into.unwrapped()) { return if into.nullable() { self.adopted(r, from, into) } else { self.rewritten(r, into) } }
        if self.reseats(from, into) { return self.reseated(r, from, into) }
        if from.stands_as(into) || from.bottom() { return r }
        if !from.reaches(into) { return self.unreached(r, from, into) }
        if into.dynamic && !into.nullable() { return self.dyn_boxed(r, from, into) }
        if into.nullable() { return self.adopted(r, from, into) }
        if into.holds_member(from) { return self.as_error(into, from, r) ?? self.missed_as("a lift into `${into.spelled()}`") }
        self.okayed(into, self.lifted(r, from, into.args[0]))
    }

    /// `r`, a value of `from` in a seat of `into` it doesn't reach: itself where the two are one thing
    /// to the machine, either isn't laid out, or the seat is `void`, which nothing reads; lifted as
    /// the shape a named seat stands over takes it, as a literal fills one; a value laid out
    /// otherwise makes no program.
    mut fn unreached(r: Reg, from: SignedType, into: SignedType) -> Reg {
        if into.owns(OwnType.Void) { return r }
        let shaped = self.shape_seat(into)
        if shaped != null && from.reaches(shaped!) { return self.lifted(r, from, shaped!) }
        let has? = self.program.checked.layout(from) else { return r }
        let wants? = self.program.checked.layout(into) else { return r }
        if has.same(wants) { r } else { self.missed_as(misseated(from, into)) }
    }

    /// The seat of `into` as the shape its named type stands over, under the nulls it carries; absent
    /// for a seat of no named type.
    fn shape_seat(into: SignedType) -> SignedType? {
        let shape? = self.named_over(into with { nulls: 0 }) else { return null }
        shape with { nulls: shape.nulls + into.nulls }
    }

    /// The template `r` as the rule's `Fix` `into`, its `Rewrite`.
    mut fn rewritten(r: Reg, into: SignedType) -> Reg {
        let tag? = self.variants_of(into)?.find_index(it.name == "Rewrite") else { return self.missed_as("a rule's `Fix` with no `Rewrite`") }
        self.tagged_value(self.laid_out(into), tag, [r])
    }

