// reference. A measurement, never a rule: its own flag, its own side tables over the slabs' range, one
// word per 16 bytes, reserved and filled by touch.
static int g_scopes_on = 0;
#define SCOPE_DEPTH (1 << 16)
static uint32_t g_scope_stack[SCOPE_DEPTH];
static int64_t g_scope_depth = 0, g_scope_lost = 0, g_scopes_opened = 0;
static uint32_t g_scope_next = 2;
static uint32_t* g_birth_scope = NULL;
static uint32_t* g_birth_site = NULL;
static int64_t g_life_born_n, g_life_born_b, g_home_n, g_home_b, g_out_n, g_out_b, g_none_n, g_none_b;
static Site g_escape_sites[SITES];
static int64_t g_escape_slots = 0;

#if AVRA_SLABS
static uint32_t* life_table(void) {
    void* r = mmap(NULL, (size_t)(g_slab_end - g_slab_base) / 16 * sizeof(uint32_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
    return r == MAP_FAILED ? NULL : (uint32_t*)r;
}
#endif

// A box born: the innermost question open, 1 where none is, and the site that made it.
static void life_born(Header* h) {
#if AVRA_SLABS
    if (!g_scopes_on || !is_slab(h)) return;
    if (g_birth_scope == NULL) { g_birth_scope = life_table(); g_birth_site = life_table(); }
    if (g_birth_scope == NULL || g_birth_site == NULL) { g_scopes_on = 0; return; }
    size_t i = (size_t)(((char*)h - g_slab_base) >> 4);
    int64_t d = g_scope_depth;
    g_birth_scope[i] = d > 0 && d <= SCOPE_DEPTH ? g_scope_stack[d - 1] : 1;
    g_birth_site[i] = mint_id(g_last_made_site);
    g_life_born_n++;
    g_life_born_b += (int64_t)(sizeof(Header) + h->len);
#else
    (void)h;
#endif
}

// Whether the question `id` is still being computed: the open stack's ids rise from its bottom.
static int scope_open(uint32_t id) {
    int64_t lo = 0, hi = (g_scope_depth < SCOPE_DEPTH ? g_scope_depth : SCOPE_DEPTH) - 1;
    while (lo <= hi) {
        int64_t mid = (lo + hi) / 2;
        if (g_scope_stack[mid] == id) return 1;
        if (g_scope_stack[mid] < id) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}

// A box dying, `block` bytes: home, escaped, or born outside every question.
static void life_noted(Header* h, int64_t block) {
#if AVRA_SLABS
    if (!g_scopes_on || g_birth_scope == NULL || !is_slab(h)) return;
    size_t i = (size_t)(((char*)h - g_slab_base) >> 4);
    uint32_t id = g_birth_scope[i];
    if (id == 0) return;
    g_birth_scope[i] = 0;
    if (id == 1) { g_none_n++; g_none_b += block; return; }
    if (scope_open(id)) { g_home_n++; g_home_b += block; return; }
    g_out_n++;
    g_out_b += block;
    uint32_t site = g_birth_site[i];
    Site* s = site_in(g_escape_sites, &g_escape_slots, site ? g_mint_site_of[site] : NULL);
    if (s) { s->made++; s->count += block; }
#else
    (void)h; (void)block;
#endif
}

static void life_report(intptr_t slide) {
    if (!g_scopes_on) return;
    avra_say("region: %lld questions computed, %lld still open at exit, %lld closes unmatched\n", (long long)g_scopes_opened,
            (long long)g_scope_depth, (long long)g_scope_lost);
    avra_say("region: born %lld boxes %lld bytes in slabs, of %lld boxes made\n", (long long)g_life_born_n, (long long)g_life_born_b,
            (long long)g_boxes_made);
    avra_say("region: died home %lld boxes %lld bytes\n", (long long)g_home_n, (long long)g_home_b);
    avra_say("region: escaped %lld boxes %lld bytes\n", (long long)g_out_n, (long long)g_out_b);
    avra_say("region: born outside any question %lld boxes %lld bytes\n", (long long)g_none_n, (long long)g_none_b);
