    avra_say("life: died escaped %lld boxes %lld bytes %lld rc\n", (long long)g_life_out_n, (long long)g_life_out_b, (long long)g_life_out_rc);
    avra_say("life: died born outside any scope %lld boxes %lld bytes %lld rc\n", (long long)g_life_none_n, (long long)g_life_none_b, (long long)g_life_none_rc);
