/// How many files a LIGHT run may read: an edit's, never a cold tree's.
const LIGHT_READS: int = 16

/// The status a run leaves with when it was asked to stay light and cannot:
/// whoever asked runs it again where heavy work is allowed. Nothing was said
/// and nothing was read.
const TOO_HEAVY: int = 75

/// `AVRA_LIGHT` asks a run to do no heavy work where it stands — the tree's
/// shim tries every package-scale `check`, `build` and `fmt` so, and sends the ones
/// that leave through the machine's watchdog.
fn light_or_leave(files: int) {
    if files > LIGHT_READS && env("AVRA_LIGHT") != null { exit(Exit.Code(TOO_HEAVY)) }
}

/// This binary's own path — the compiler a store's rows are the work of: the file the running image
/// was started from, its links resolved, never another file named as it was invoked.
fn own_binary() -> string? {
    let at = avra_self_path()
    if at.is_empty() { null } else { at }
}

/// THE RUNNING COMPILER'S PRINT: its binary's bytes as one digest, settled
/// once a process — a binary rebuilt under a running process is not the
/// code that runs. THE ONE IDENTITY EVERY KEPT ARTIFACT'S KEY HOLDS: an
/// object, a link, a suite binary, an agreement, a machine store's answers
/// — whatever a compiler made is another compiler's only where their bytes
/// are one, whatever in them moved: its sources, its C, its LLVM. A record beside the binary names that digest for the
/// binary's stamp (size, times, inode): the bytes are read again when the
/// stamp differs, the path differs, or the host cannot tell (a file written
/// too recently to trust). The value is the bytes' digest either way.
once fn own_print() -> string? {
    let at? = own_binary() else { return null }
    let mark? = stamp(at) else {
        let read? = digest_of_binary(at) else { return null }
        printed_by("bytes", read)
        return read
    }
    let head = "${mark}\t${at}\t"
    let kept = read_text(print_record(at)) catch ""
    if kept.starts_with(head) {
        let digest = kept.substring(head.length, kept.length)
        printed_by("stamp", digest)
        return digest
    }
    let made? = digest_of_binary(at) else { return null }
    let _ = write_text(print_record(at), "${head}${made}")
    printed_by("bytes", made)
    made
}

