cd /work/avra/packages/std-program/src && python3 - <<'P'
p='frontier.av';t=open(p).read()
old_doc='''    /// among them is, so what it meets is final. A place that read a place that moved (a changed one,
    /// or a cut `decide` found moved) is decided: a cut that stands (`CUT_STANDS`) was just worked out
    /// equal, so it is neither reached nor walked past; one that moved (`CUT_MOVED`) is reached and
    /// moved; one that doesn't cut is reached. A place that read only places merely reached is reached
    /// undecided. So the places reached, and the places decided, are the same whatever order the
    /// frontier keeps its places in: a hash that moves with unrelated code moves no warm work.'''
new_doc='''    /// among them is, so what it meets is final. Each place that read a place reached is decided, the
    /// change reaching it through a place that moved or one merely reached alike: a cut that stands
    /// (`CUT_STANDS`) was just worked out equal, so it is neither reached nor walked past; any other is
    /// reached. So the places reached, and the places decided, are the same whatever order the
    /// frontier keeps its places in: a hash that moves with unrelated code moves no warm work.'''
assert old_doc in t; t=t.replace(old_doc,new_doc)
old='''        // Each place settled once all it reads among them are: moved, reached, or neither.
        mut changed_here = [false for _i in 0..self.extent]
        for c in changed { changed_here.set(c, true) }
        mut moved = [false for _i in 0..self.extent]
        mut reached = [false for _i in 0..self.extent]
        mut met_moved = [false for _i in 0..self.extent]
        mut met_reached = [false for _i in 0..self.extent]
'''
new='''        // Each place settled once all it reads among them are: reached, or cut off.
        mut changed_here = [false for _i in 0..self.extent]
        for c in changed { changed_here.set(c, true) }
        mut reached = [false for _i in 0..self.extent]
        mut met = [false for _i in 0..self.extent]
'''
assert old in t; t=t.replace(old,new)
old='''            if changed_here[at] {
                moved.set(at, true)
                reached.set(at, true)
            } else if met_moved[at] {
                let decided = decide(at)
                if decided != CUT_STANDS { reached.set(at, true) }
                if decided == CUT_MOVED { moved.set(at, true) }
            } else if met_reached[at] { reached.set(at, true) }
            for r in next[at] {
                if moved[at] { met_moved.set(r, true) } else if reached[at] { met_reached.set(r, true) }
'''
new='''            if changed_here[at] { reached.set(at, true) } else if met[at] && decide(at) != CUT_STANDS { reached.set(at, true) }
            for r in next[at] {
                if reached[at] { met.set(r, true) }
'''
assert old in t; t=t.replace(old,new)
open(p,'w').write(t)
P
