        mut next: List<List<int>> = [[] for _i in 0..self.extent]
        mut waiting = [0 for _i in 0..self.extent]
        mut named_by = [-1 for _i in 0..self.extent]
        mut pending = changed
        while !pending.is_empty() {
            let at = pending.pop()
            if reachable[at] { continue }
