/// Which param registers a consuming seat mark names — this body's
/// OWN birth credit for each, arriving with the call rather than an
/// instruction in its stream.
/// A LENT ANSWER IS A VIEW: in a body whose marks lend its answer from some seats, every register the
/// answer may be — each arm a region merges, each box a lending read or Extract projects from — rides
/// a seat the caller keeps standing past the call, so here it is counted by no retain and freed by
/// no release, as the binary's own data is. Re-derived from the stream: a chain that roots anywhere
/// but a lent seat exempts nothing, and what it left uncounted is reported as any other.
fn lent_chain(b: Body) -> List<bool> {
    let n = b.layouts.length
    let none = [false for j in 0..n]
    if !b.marks.any(it.lent) { return none }
    let defs = def_sites(n, b.ins)
    mut out = [false for j in 0..n]
    mut todo: List<Reg> = flatten([answered_regs(i) for i in b.ins])
    while !todo.is_empty() {
        let r = todo.pop()
        if r.index < 0 || r.index >= n { return none }
        if out[r.index] { continue }
        out.set(r.index, true)
        let d = defs[r.index]
        if d < 0 {
            if r.index >= b.seats.length || !lent_seat(b.marks, r.index) { return none }
            continue
        }
        let i = b.ins[d]
        if i is .RegionEnd {
            let open? = region_opener(b.ins, d) else { return none }
            for a in region_arms(b.ins, open) { if !arm_diverges(b.ins, a) { todo.push(a.gives) } }
            continue
        }
        let src? = view_source(i) else { return none }
        todo.push(src)
    }
    out
}

fn lent_seat(marks: List<SeatMark>, j: int) -> bool { j < marks.length && marks[j].lent }

fn answered_regs(i: Ins) -> List<Reg> {
    match i { .RetVal(r) or .FnExit(r) -> [r], rest -> [] }
}

/// The `IfStart`/`SwitchStart` the `RegionEnd` at `end_at` closes.
fn region_opener(ins: List<Ins>, end_at: int) -> int? {
