export type AnswerChain = { regs: List<bool>, seats: List<bool> }

/// THE SEATS A BODY LENDS ITS ANSWER FROM: of the `eligible` ones among its first `seats` registers,
/// those its answer's chain roots in, where every answer it gives — the tail, each early exit, each
/// arm of a region it merges — is a field, index or arm projection of an eligible seat, with no cell
/// on the way. None where any answer is a box of its own: a fresh one, a call's, a cell's load.
export fn lent_seats(ins: List<Ins>, layouts: List<Layout>, seats: int, eligible: List<bool>) -> List<
    bool,
> {
    let chain? = answer_chain(ins, layouts, seats, eligible) else { return [] }
    if !chain.seats.any(it) { return [] }
    chain.seats
}

/// The answer's chain over `ins`, absent where some answer is no projection of an `eligible` seat.
export fn answer_chain(ins: List<Ins>, layouts: List<Layout>, seats: int, eligible: List<bool>) -> AnswerChain? {
    let defs = def_sites(layouts.length, ins)
    let arms = merged_arms(ins, layouts.length)
    mut regs = [false for j in 0..layouts.length]
    mut roots = [false for j in 0..seats]
    mut todo: List<Reg> = [r! for i in ins for r in [answered_reg(i)] if r != null]
    if todo.is_empty() { return null }
    while !todo.is_empty() {
        let r = todo.pop()
        if r.index < 0 { return null }
        if regs[r.index] { continue }
        regs.set(r.index, true)
        let shape = layouts[r.index]
        if !(shape is .Boxed) || shape.carries_cell() { return null }
        let d = defs[r.index]
        if d < 0 {
            if r.index >= seats || !(r.index < eligible.length && eligible[r.index]) { return null }
            roots.set(r.index, true)
            continue
        }
        let yields = arms[r.index]
        if !yields.is_empty() {
            for g in yields { todo.push(g) }
            continue
        }
        let i = ins[d]
        let viewed? = view_of(i) else { return null }
        if viewed.index != r.index { return null }
        let src? = view_source(i) else { return null }
        todo.push(src)
    }
    // a step that writes a register of the chain where it stands would write the caller's box
    for i in ins {
        let written = match i {
            .CallRt(_, callee, args) or .CallRtVoid(callee, args) -> args.any((a: Reg) -> among(regs, a) && writes_arg(callee, args, a)),
            rest -> false,
        }
        if written { return null }
    }
    AnswerChain { regs: regs, seats: roots }
}

/// The register an answering step hands the caller.
fn answered_reg(i: Ins) -> Reg? {
    match i { .RetVal(r) or .FnExit(r) -> r, rest -> null }
}

/// Each region's merged register's arms' yields, by the merged register; an arm that never falls
/// through yields nothing.
fn merged_arms(ins: List<Ins>, count: int) -> List<List<Reg>> {
    mut out: List<List<Reg>> = [[] for j in 0..count]
    for k, i in ins {
        if !(i is .IfStart || i is .SwitchStart) { continue }
        let close = region_exit(ins, k)
        let merged? = region_dst(ins[close]) else { continue }
        mut gives: List<Reg> = []
        mut j = k
        while j < close {
            let exit = arm_exit(ins, j + 1)
            j = exit.boundary
            if !exit.diverges { gives.push(arm_gives(ins[j])) }
        }
        out.set(merged.index, gives)
    }
    out
}
