trait Sem {
    fn go(mut c: Cx, n: int) -> int
}

type A = { k: int }
type B = { k: int }

impl Sem for A {
    fn go(mut c: Cx, n: int) -> int { self.k + n + c.count }
}

impl Sem for B {
    fn go(mut c: Cx, n: int) -> int { self.k * n + c.count }
}

enum Pat { Wild, Named(string), Pair(int, int) }

type Store = { pats: List<Pat> }

impl Store {
    fn pat(i: int) -> Pat { self.pats[i] }
}

type View = { store: Store }

type D = { a: dyn Sem, b: dyn Sem }

type Cx = { d: D, view: View, count: int }

fn pick(d: D, p: Pat) -> dyn Sem {
    match p {
        .Wild or .Named(_) -> d.a,
        .Pair(_, _) -> d.b,
    }
}

fn run_one(mut c: Cx, n: int) -> int {
    pick(c.d, c.view.store.pat(n)).go(c, n)
}

fn run() -> string {
    mut c = Cx { d: D { a: A { k: 3 }, b: B { k: 4 } }, view: View { store: Store { pats: [Pat.Wild, Pat.Named("x${1}"), Pat.Pair(1, 2)] } }, count: 1 }
    "${run_one(c, 2)} ${run_one(c, 1)} ${run_one(c, 0)}"
}

