// proves: an answer that projects a seat — a field, an index read, an arm — is read by its caller as
// a view of the argument, which stands while the view is read, and keeps a count of its own where the
// view outlives what it rides: a source overwritten, rebound, consumed, emptied through a `mut` seat,
// a view yielded out of the scope that made its source or stored past it; a recursion, a `dyn` box
// and a fn value answer what a direct call does, and each fill of a generic fn lends as its own
// answer allows. Every box is made at run time, so a view that dangles reads a freed one.
type Node = { name: string, kids: List<Node>, tags: List<string> }

type Arena = { nodes: List<Node> }

type Bag = { rows: List<List<string>>, tag: string }

trait Tagged {
    fn tag() -> string
}

impl Tagged for Node {
    fn tag() -> string { self.tags[0] }
}

