/// A body with each lent answer read as a view, and the call answers that own nothing, by register.
type LentReads = { body: Body, unmanaged: List<bool> }

/// THE CALLER'S ONE RULE: a call to a body that lends its answer from some seats answers a register
/// that owns nothing, read through `avra_lent_view` as a view of each argument it lends from, one
/// after another, the last read being the call's own destination. A view that outlives what it rides
/// takes the row's owned twin, as any lending read does. The registers a read adds stand just below
/// the call's destination and every later register moves up by as many, so each instruction still
/// defines the next register.
fn lent_reads(b: Body, by_name: Map<string, List<SeatMark>>) -> LentReads {
    let lends = [lent_sources(b.layouts, by_name, i) for i in b.ins]
    if lends.all(it.is_empty()) { return LentReads { body: b, unmanaged: [] } }
    let added = lent_added(b.layouts.length, b.ins, lends)
    let places = moved_places(added)
    let at = (r: Reg) -> if r.index < 0 || r.index >= places.length { r } else { Reg { index: places[r.index] } }
    mut out: List<Ins> = []
    mut owning_none: List<int> = []
    for k, i in b.ins {
        let call? = lent_call(i) else {
            out.push(remapped(i, at))
            continue
        }
        let srcs = lends[k]
        if srcs.is_empty() {
            out.push(remapped(i, at))
            continue
        }
        let base = places[call.dst.index] - srcs.length
        owning_none.push(base)
        out.push(Ins.Call(Reg { index: base }, call.callee, [at(a) for a in call.args]))
        for j, src in srcs { out.push(Ins.CallRt(Reg { index: base + j + 1 }, LENT_VIEW, [at(src), Reg { index: base + j }])) }
    }
    let count = places.length
    LentReads {
        body: b with {
            ins: out,
            gives: if b.gives == null { null } else { at(b.gives!) },
            layouts: grown(b.layouts, added),
            reg_types: grown(b.reg_types, added),
            boxed: [v with { reg: at(Reg { index: v.reg }).index } for v in b.boxed],
        },
        unmanaged: [owning_none.contains(j) for j in 0..count],
    }
