/// How many registers each register's lent read adds below it, by register: a lent call's
/// destination gains one a seat it lends from.
fn lent_added(count: int, ins: List<Ins>, lends: List<List<Reg>>) -> List<int> {
    mut added = [0 for j in 0..count]
    for k, i in ins {
        let call? = lent_call(i) else { continue }
        added.set(call.dst.index, added[call.dst.index] + lends[k].length)
    }
    added
