fn moved_places(added: List<int>) -> List<int> {
    mut places: List<int> = []
    mut moved = 0
    for r, a in added {
        moved = moved + a
        places.push(r + moved)
    }
    places
}

/// A per-register table with each register's entry repeated for the registers added below it.
fn grown<T>(table: List<T>, added: List<int>) -> List<T> {
    flatten([filled(if r < added.length { added[r] + 1 } else { 1 }, v) for r, v in table])
