/// parts from its leaves' seats — every instruction emits, and the verifier
/// gates where `verified`: every build but a level-0 object, and that one too
/// under `AVRA_VERIFY_LLVM`. Where `answers_out`, a value of parts is
/// answered through a pointer the caller lends, the fn's last seat.
fn emit_body(
    lc: ptr,
    m: ptr,
    b: ptr,
    types: TypeRegistry,
    externs: List<RtSig>,
    rt: Map<string, RtSig>,
    bd: Body,
    f: ptr,
    unwinds: bool,
    verified: bool,
    answers_out: bool,
) -> string? {
    mut vals: List<ptr> = []
    mut leaves: List<List<ptr>> = []
    mut joined: List<bool> = []
    mut param = 0
    for s in bd.seats {
        if splits(s) {
            let count = leaf_layouts(s).length
            leaves.push([avra_llvm_get_param(f, param + k) for k in 0..count])
            vals.push(avra_llvm_get_undef(ll_layout(lc, s)))
            joined.push(false)
            param = param + count
        } else {
            leaves.push([])
            vals.push(avra_llvm_get_param(f, param))
            joined.push(true)
            param = param + 1
        }
    }
    let answer = bd.answer ?? Layout.Void
    let out = if answers_out && splits(answer) { [avra_llvm_get_param(f, param)] } else { [] }
