/// One body's memory instructions: its params are registers 0..`seats`, and
/// every scope's exit names what escapes it. A CONSUMING seat (R3) is the one
/// exception to "a param stands": its whole point is to be scope-owned from
/// entry, so `consuming_seats` seeds it into the entry scope the moment the first
/// bracket opens, and every caller of THIS body reads `marks` by name to
/// decide whether to hand its dying argument over or retain first.
fn body_ins(
    layouts: List<Layout>,
    ins: List<Ins>,
    seats: int,
    marks: List<SeatMark>,
    by_name: Map<string, List<SeatMark>>,
    unmanaged: List<bool> = [],
) -> List<Ins> {
    let immortal = immortal_regs(layouts.length, ins)
    runs_joined(
        noted_pairs(
            [i for i in memory_ins(
                layouts,
                ins,
                standing_regs(immortal, ins, seats, marks),
                consuming_seats(seats, marks),
                by_name,
                lent_answer(ins, layouts, seats, marks),
                unmanaged,
            ) if !immortal_rc_op(i, immortal)],
        ),
    )
}

/// `b` past the memory pass: each call to a body that lends its answer read as a view of the
/// arguments it lends from, then every count placed. `seats` is how many registers are its seats.
fn body_made(b: Body, by_name: Map<string, List<SeatMark>>, seats: int = 0 - 1) -> Body {
    let read = lent_reads(b.layouts, b.ins, by_name)
    let n = if seats < 0 { b.seats.length } else { seats }
    b with { ins: body_ins(read.layouts, read.ins, n, b.marks, by_name, read.unmanaged), layouts: read.layouts }
}

