type LentReads = { ins: List<Ins>, layouts: List<Layout>, unmanaged: List<bool> }

/// THE CALLER'S ONE RULE: a call to a body that lends its answer from some seats answers a register
/// that owns nothing, read through `avra_lent_view` as a view of each argument it lends from, one
/// after another, the last read being the call's own destination. A view that outlives what it rides
/// takes the row's owned twin, as any lending read does.
fn lent_reads(layouts: List<Layout>, ins: List<Ins>, by_name: Map<string, List<SeatMark>>) -> LentReads {
    if !ins.any(!lent_sources(layouts, by_name, it).is_empty()) {
        return LentReads { ins: ins, layouts: layouts, unmanaged: [] }
    }
    mut out: List<Ins> = []
    mut shapes: List<Layout> = [l for l in layouts]
    mut bare: List<int> = []
    for i in ins {
        let srcs = lent_sources(layouts, by_name, i)
        let call? = lent_call(i) else {
            out.push(i)
            continue
        }
        if srcs.is_empty() {
            out.push(i)
            continue
        }
        let shape = layouts[call.dst.index]
        let answer = Reg { index: shapes.length }
        shapes.push(shape)
        bare.push(answer.index)
        out.push(Ins.Call(answer, call.callee, call.args))
        mut held = answer
        for k, src in srcs {
            let last = k == srcs.length - 1
            let viewed = if last { call.dst } else { Reg { index: shapes.length } }
            if !last { shapes.push(shape) }
            out.push(Ins.CallRt(viewed, LENT_VIEW, [src, held]))
            held = viewed
        }
    }
    mut unmanaged = [false for j in 0..shapes.length]
    for j in bare { unmanaged.set(j, true) }
    LentReads { ins: out, layouts: shapes, unmanaged: unmanaged }
}

