// numbers are still the slots'.
void avra_pool_forked(void) {
    for (int i = 0; i < g_held_count; i++) close(g_held[i]);
    g_held_count = 0;
}

// The pool's size and directory, settled on first use. No pool when it's turned off, sized to
// nothing, or its directory can't be made.
static void pool_settled(void) {
    if (g_slot_count >= 0) return;
    g_slot_count = 0;
    const char* sized = getenv("AVRA_MEM_POOL_MB");
    int64_t bytes = sized && *sized ? (int64_t)atoll(sized) << 20 : machine_bytes() / 100 * POOL_PERCENT;
    const char* waits = getenv("AVRA_MEM_POOL_WAIT_MS");
    if (waits && *waits) g_wait_ms = atoll(waits);
    if (bytes <= 0) return;
    const char* placed = getenv("AVRA_MEM_POOL_DIR");
    if (placed && *placed) {
        snprintf(g_dir, sizeof g_dir, "%s", placed);
    } else {
        char base[PATH_BYTES];
        avra_user_dir(base, sizeof base);
        mkdir(base, 0700);
        snprintf(g_dir, sizeof g_dir, "%s/avra-pool", base);
    }
    if (mkdir(g_dir, 0700) != 0 && errno != EEXIST) return;
    int64_t slots = bytes / SLOT_BYTES;
    g_slot_count = (int)(slots < 1 ? 1 : slots > MOST_SLOTS ? MOST_SLOTS : slots);
}

// One free slot taken, its file naming this process, or -1 when every slot is held.
static int slot_taken(void) {
    for (int i = 0; i < g_slot_count; i++) {
        char path[PATH_BYTES];
        snprintf(path, sizeof path, "%s/slot-%d", g_dir, i);
        int fd = open(path, O_RDWR | O_CREAT | O_CLOEXEC, 0600);
        if (fd < 0) continue;
        if (flock(fd, LOCK_EX | LOCK_NB) == 0) {
            char pid[24];
            int n = snprintf(pid, sizeof pid, "%d\n", (int)getpid());
            if (ftruncate(fd, 0) == 0) { ssize_t w = pwrite(fd, pid, (size_t)n, 0); (void)w; }

// `taking` is what the caller is about to take: the look judges the use it is about to have.
__attribute__((noinline, cold))
static void mem_ceiling_measure(int64_t taking) {
    int64_t used = mem_in_use() + taking;
    if (used > g_mem_ceiling) {
        char msg[96];
        avra_fmt(msg, sizeof msg, "memory ceiling exceeded: %lld MB (AVRA_MEM_CEILING_MB)",
               (long long)(g_mem_ceiling >> 20));
        avra_trap(msg); // LICENSED traps.process_limit: the memory ceiling is a limit of the process
    }
    int64_t allowed = avra_pool_allowed(used);
    if (allowed < 0) {
        char msg[160];
        if (allowed == -1) {
            avra_fmt(msg, sizeof msg, "this run needs more than the machine's whole memory pool: %lld MB in use (AVRA_MEM_POOL_MB)",
                   (long long)(used >> 20));
        } else if (allowed == -2) {
            avra_fmt(msg, sizeof msg, "other runs held the machine's memory pool past this run's wait: %lld MB in use (AVRA_MEM_POOL_WAIT_MS)",
                   (long long)(used >> 20));
        } else {
            avra_fmt(msg, sizeof msg, "the machine's memory pool is held wholly by runs waiting for more, and this run holds the least of it: %lld MB in use",
                   (long long)(used >> 20));
        }
        avra_trap(msg); // LICENSED traps.process_limit: the pool is a limit of the machine
    }
